public Yaf_DispatchernullYaf_Dispatcher::setView Yaf_View_Interfaceview
Cette méthode fournit une solution pour utiliser un moteur de vue personnalisé au lieu de Yaf_View_Simple

&reftitle.returnvalues;

 Retourne l'objet Yaf_Dispatcher lui-même en cas de
 succès, ou &null; si l'application n'est pas initialisée.

  &reftitle.examples;

   Exemple de moteur de vue personnalisé


<?php
require "/path/to/smarty/Smarty.class.php";

class Smarty_Adapter implements Yaf_View_Interface
{
    /**
     * Objet Smarty
     * @var Smarty
     */
    public $_smarty;

    /**
     * Constructeur
     *
     * @param string $tmplPath
     * @param array $extraParams
     * @return void
     */
    public function __construct($tmplPath = null, $extraParams = array()) {
        $this->_smarty = new Smarty;

        if (null !== $tmplPath) {
            $this->setScriptPath($tmplPath);
        }

        foreach ($extraParams as $key => $value) {
            $this->_smarty->$key = $value;
        }
    }

    /**
     * Définit le chemin vers les templates
     *
     * @param string $path Le dossier à définir comme chemin.
     * @return void
     */
    public function setScriptPath($path)
    {
        if (is_readable($path)) {
            $this->_smarty->template_dir = $path;
            return;
        }

        throw new Exception('Chemin fourni invalide');
    }

    /**
     * Assigne une variable au template
     *
     * @param string $key Le nom de la variable.
     * @param mixed $val La valeur de la variable.
     * @return void
     */
    public function __set($key, $val)
    {
        $this->_smarty->assign($key, $val);
    }

    /**
     * Permet le fonctionnement des tests avec empty() et isset()
     *
     * @param string $key
     * @return boolean
     */
    public function __isset($key)
    {
        return (null !== $this->_smarty->get_template_vars($key));
    }

    /**
     * Permet le fonctionnement de unset() sur les propriétés de l'objet
     *
     * @param string $key
     * @return void
     */
    public function __unset($key)
    {
        $this->_smarty->clear_assign($key);
    }

    /**
     * Assigne des variables au template
     *
     * Permet de définir une clé spécifique à la valeur indiquée, OU de
     * passer un tableau de paires clé => valeur pour une définition en masse.
     *
     * @see __set()
     * @param string|array $spec La stratégie d'assignation à utiliser (clé ou
     * tableau de paires clé => valeur)
     * @param mixed $value (Optionnel) Lors de l'assignation d'une variable
     * nommée, utilise ceci comme valeur.
     * @return void
     */
    public function assign($spec, $value = null) {
        if (is_array($spec)) {
            $this->_smarty->assign($spec);
            return;
        }

        $this->_smarty->assign($spec, $value);
    }

    /**
     * Efface toutes les variables assignées
     *
     * Efface toutes les variables assignées à Yaf_View, que ce soit via
     * {@link assign()} ou par surcharge de propriété
     * ({@link __get()}/{@link __set()}).
     *
     * @return void
     */
    public function clearVars() {
        $this->_smarty->clear_all_assign();
    }

    /**
     * Traite un template et retourne les données de sortie.
     *
     * @param string $name Le template à traiter.
     * @return string Les données de sortie.
     */
    public function render($name, $value = NULL) {
        return $this->_smarty->fetch($name);
    }

    public function display($name, $value = NULL) {
        echo $this->_smarty->fetch($name);
    }

}
?>




   Exemple avec Yaf_Dispatcher::setView


<?php
class Bootstrap extends Yaf_Bootstrap_Abstract {

    /**
     * il y a quelques options de configuration pour smarty dans la configuration :
     *
     * smarty.left_delimiter   = "{{"
     * smarty.right_delimiter  = "}}"
     * smarty.template_dir     = APPLICATION_PATH "/views/scripts/"
     * smarty.compile_dir      = APPLICATION_PATH "/views/templates_c/"
     * smarty.cache_dir        = APPLICATION_PATH "/views/templates_d/"
     *
     */
    public function _initConfig() {
        $config = Yaf_Application::app()->getConfig();
        Yaf_Registry::set("config", $config);
    }

    public function _initLocalName() {
        /** la classe Smarty_Adapter est placée dans le dossier local des bibliothèques */
        Yaf_Loader::getInstance()->registerLocalNamespace('Smarty');
    }

    public function _initSmarty(Yaf_Dispatcher $dispatcher) {
        $smarty = new Smarty_Adapter(null, Yaf_Registry::get("config")->get("smarty"));
        $dispatcher->setView($smarty);
        /* désormais, le moteur de vue Smarty devient le moteur de vue par défaut de Yaf */
    }
}
?>
